import{_ as r,c as i,o as n,j as d,a8 as t,t as s,a as l}from"./chunks/framework.jsZJWZJf.js";const q=JSON.parse('{"title":"身为女性的选择 - 读书笔记","description":"","frontmatter":{"title":"身为女性的选择 - 读书笔记","outline":[2,2],"finishedDate":"2025-06-13"},"headers":[],"relativePath":"blog/read/books/身为女性的选择.md","filePath":"blog/read/books/身为女性的选择.md","lastUpdated":1795017144000}'),v={name:"blog/read/books/身为女性的选择.md"},c={class:"social-psychology-notes"},p={class:"reading-book","aria-label":"书籍信息"},o={class:"reading-book-info"},f={class:"reading-metadata"},b=["datetime"];function h(e,a,u,x,k,g){return n(),i("div",null,[d("div",c,[a[8]||(a[8]=d("header",{class:"reading-header"},[d("h1",null,"身为女性的选择"),d("p",{class:"reading-byline"},"作者：【日】上野千鹤子 【日】信田小夜子"),d("div",{class:"reading-stats"},[d("span",null,"35 条摘抄"),d("span",null,"微信读书")])],-1)),d("section",p,[a[7]||(a[7]=d("div",{class:"reading-cover"},[d("img",{src:"https://cdn.weread.qq.com/weread/cover/79/cpplatform_4glhvzqsrzssk69qec6idk/t6_cpplatform_4glhvzqsrzssk69qec6idk1677835601.jpg",alt:"身为女性的选择封面",width:"160",loading:"lazy"})],-1)),d("div",o,[a[4]||(a[4]=d("p",{class:"reading-book-title"},"书籍信息",-1)),d("dl",f,[a[1]||(a[1]=t("<div data-v-2f4d61ed><dt data-v-2f4d61ed>书名</dt><dd data-v-2f4d61ed>身为女性的选择</dd></div><div data-v-2f4d61ed><dt data-v-2f4d61ed>作者</dt><dd data-v-2f4d61ed>【日】上野千鹤子 【日】信田小夜子</dd></div><div data-v-2f4d61ed><dt data-v-2f4d61ed>出版社</dt><dd data-v-2f4d61ed>国际文化出版公司</dd></div><div data-v-2f4d61ed><dt data-v-2f4d61ed>出版时间</dt><dd data-v-2f4d61ed>2023-02-28 00:00:00</dd></div>",4)),d("div",null,[a[0]||(a[0]=d("dt",null,"完读日期",-1)),d("dd",null,[d("time",{datetime:e.$frontmatter.finishedDate},s(e.$frontmatter.finishedDate),9,b)])]),a[2]||(a[2]=d("div",null,[d("dt",null,"ISBN"),d("dd",null,"9787512514959")],-1)),a[3]||(a[3]=d("div",null,[d("dt",null,"分类"),d("dd",null,"社会文化-社科")],-1))]),a[5]||(a[5]=d("a",{class:"reading-original-link",href:"https://weread.qq.com/web/reader/20a32910813ab7a76g012e28",target:"_blank",rel:"noopener noreferrer"},[l("在微信读书中打开 "),d("span",{"aria-hidden":"true"},"↗")],-1)),a[6]||(a[6]=d("details",{class:"reading-description"},[d("summary",null,"书籍简介"),d("p",null,"著名女性主义学者上野千鹤子写给所有女性的清醒之书！中文简体版首次引进！“这场辩论是因为我们彼此信任”。围绕女性关注的亲密关系、婚恋、独立等议题，社会学家上野千鹤子与心理学家信田小夜子，开始了一场女性主义的尖锐问答。两位“女性的盟友”分别从社会学统计数据与一线女性的心境出发，结合各自的观察和研究经验，以女性视角讨论和思考现行婚姻制度与女性面临的婚恋现实，百无禁忌地畅谈爱情观、社会性别、男性观察、母女关系等女性日常生活中无法逃避的话题，敞开心扉，直言不讳。两位学者借独到的观点和犀利的语言，鼓舞女性活出自我，自由选择自己的人生！")],-1))])]),a[9]||(a[9]=t('<h2 id="在-40代-开始升高的欲望水压" tabindex="-1" data-v-2f4d61ed>在“40代”开始升高的欲望水压 <a class="header-anchor" href="#在-40代-开始升高的欲望水压" aria-label="Permalink to “在“40代”开始升高的欲望水压”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>001</span><div data-v-2f4d61ed><p data-v-2f4d61ed>只有发生了比较，才会产生悲惨的认知，若没有比较对象，人就意识不到自己的悲惨和贫瘠。</p></div></blockquote><h2 id="对-30代-的-相对剥夺" tabindex="-1" data-v-2f4d61ed>对“30代”的“相对剥夺” <a class="header-anchor" href="#对-30代-的-相对剥夺" aria-label="Permalink to “对“30代”的“相对剥夺””" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-002" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>002</span><div data-v-2f4d61ed><p data-v-2f4d61ed>换言之，就是烂苹果无须吃到最后一口才幡然醒悟</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-003" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>003</span><div data-v-2f4d61ed><p data-v-2f4d61ed>他可能一直觉得女人都这样，婚姻都这样。这种情况就叫相对剥夺，主妇的身份远比以前更有压力了。</p></div></blockquote><h2 id="不保养就活不下去" tabindex="-1" data-v-2f4d61ed>不保养就活不下去？ <a class="header-anchor" href="#不保养就活不下去" aria-label="Permalink to “不保养就活不下去？”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-004" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>004</span><div data-v-2f4d61ed><p data-v-2f4d61ed>由于自我的证明已经崩溃，人们才要支付金钱，请不相关的第三者为自我提供确证。</p></div></blockquote><h2 id="空洞化的恶果落到谁头上" tabindex="-1" data-v-2f4d61ed>空洞化的恶果落到谁头上？ <a class="header-anchor" href="#空洞化的恶果落到谁头上" aria-label="Permalink to “空洞化的恶果落到谁头上？”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-005" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>005</span><div data-v-2f4d61ed><p data-v-2f4d61ed>彼此保持距离，尽量不造成伤害，最大限度共存的关系更安全。毕竟世上不存在“十全十美的家庭”</p></div></blockquote><h2 id="婚姻的快感与陶醉" tabindex="-1" data-v-2f4d61ed>婚姻的快感与陶醉 <a class="header-anchor" href="#婚姻的快感与陶醉" aria-label="Permalink to “婚姻的快感与陶醉”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-006" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>006</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我认为不可思议的是，人为什么会产生管理他人身体，或者拥有支配他人身体的权利的这种错觉。对方在别的地方使用了自己的身体，他就觉得自己有权利谴责“你竟然背叛了我”。这究竟是为什么？我真的百思不得其解。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-007" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>007</span><div data-v-2f4d61ed><p data-v-2f4d61ed>尤其是女性，应该是把婚姻这个台阶当成了往后人生的保证。虽不知道她们是否具备将性的使用权让渡给单独个体的意识，但是，“他只有我一个人”的快感使人更加陶醉于婚姻，再加上重启人生的幻想，就形成了结婚意愿。</p></div></blockquote><h2 id="支配与疼爱互为表里" tabindex="-1" data-v-2f4d61ed>支配与疼爱互为表里 <a class="header-anchor" href="#支配与疼爱互为表里" aria-label="Permalink to “支配与疼爱互为表里”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-008" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>008</span><div data-v-2f4d61ed><p data-v-2f4d61ed>无论多么糟糕的男人，最后都有一个女人跟随他，世上真有这等好事吗？只能依赖那种故事生存的男人，究竟算什么？不就是依靠比自己弱小、比自己弱势的性别来确立自身吗？其实真正的寄生虫，应该是男性才对</p></div></blockquote><h2 id="男人的根基被动摇" tabindex="-1" data-v-2f4d61ed>男人的根基被动摇 <a class="header-anchor" href="#男人的根基被动摇" aria-label="Permalink to “男人的根基被动摇”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-009" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>009</span><div data-v-2f4d61ed><p data-v-2f4d61ed>他们通过将责任转嫁给妻子的方式，正当化了自己的行为。因为很多男人会说：“我都是为了妻子才经营着家庭。”他们可狡猾了。基本不会有男人傻乎乎地直说“老婆不遵从我的支配”</p></div></blockquote><h2 id="能言善辩的男人也会动手的谜团" tabindex="-1" data-v-2f4d61ed>能言善辩的男人也会动手的谜团 <a class="header-anchor" href="#能言善辩的男人也会动手的谜团" aria-label="Permalink to “能言善辩的男人也会动手的谜团”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-010" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>010</span><div data-v-2f4d61ed><p data-v-2f4d61ed>假设一对夫妻在吵架，妻子对丈夫倾诉了自己的不满，丈夫则满脸忧愁地听着，等待暴风雨过去。他听见了妻子的声音，但没有去识别妻子的话语。<br data-v-2f4d61ed>妻子说啊说啊，最后因愤怒而筋疲力尽，不再说话。等到暴风雨过去了，满脸忧愁的丈夫就会说：“去吃点好吃的吧。”就这样，夫妻俩相处了不知多少年。有的女性会忍无可忍，提出离婚。说白了，二者之间连吵架这种沟通方式都从未成立过。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-011" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>011</span><div data-v-2f4d61ed><p data-v-2f4d61ed>如果说沟通并非单纯的独白，而是对话，而对话是一种交涉的技术，那么你说的案例中，就不存在交涉。它只是独白的不断堆叠。</p></div></blockquote><h2 id="人不打会还手的人" tabindex="-1" data-v-2f4d61ed>人不打会还手的人 <a class="header-anchor" href="#人不打会还手的人" aria-label="Permalink to “人不打会还手的人”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-012" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>012</span><div data-v-2f4d61ed><p data-v-2f4d61ed>没生过孩子的女人反倒更容易信奉母爱神话，会说出：“她难道不爱孩子吗？”其实并非如此。</p></div></blockquote><h2 id="离了婚就是结婚帝国的难民" tabindex="-1" data-v-2f4d61ed>离了婚就是结婚帝国的难民 <a class="header-anchor" href="#离了婚就是结婚帝国的难民" aria-label="Permalink to “离了婚就是结婚帝国的难民”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-013" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>013</span><div data-v-2f4d61ed><p data-v-2f4d61ed>大家都说离了婚的女人过得很爽，其实她们在社会上的确是无依无靠的存在。不仅如此，还真实地暴露在明显的歧视以及来自男性的性接触和侮辱行为中</p></div></blockquote><h2 id="孩子是自保的手段" tabindex="-1" data-v-2f4d61ed>孩子是自保的手段 <a class="header-anchor" href="#孩子是自保的手段" aria-label="Permalink to “孩子是自保的手段”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-014" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>014</span><div data-v-2f4d61ed><p data-v-2f4d61ed>看了母亲们的行动，就会明白母爱只是空谈。我反倒看清楚了，女人从来只会最优先自己的利益。她们明明看到孩子受了这么大的伤害，怎么就不想想如何拯救孩子脱离那样的环境呢？这最终会演变为虐待，比如孩子遭受的性伤害</p></div></blockquote><h2 id="留在dv丈夫身边的理由" tabindex="-1" data-v-2f4d61ed>留在DV丈夫身边的理由 <a class="header-anchor" href="#留在dv丈夫身边的理由" aria-label="Permalink to “留在DV丈夫身边的理由”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-015" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>015</span><div data-v-2f4d61ed><p data-v-2f4d61ed>孤独”并不等同于“独自一人”。在旁人看来，相对无言的孤独、夫妻关系的地狱、不得不与缺乏沟通能力的人共同生活的“孤独”，都比一个人的“孤独”更难以忍受啊！</p></div></blockquote><h2 id="那个人很强大-可是我" tabindex="-1" data-v-2f4d61ed>“那个人很强大，可是我……” <a class="header-anchor" href="#那个人很强大-可是我" aria-label="Permalink to ““那个人很强大，可是我……””" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-016" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>016</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我很明白你正处在如入泥沼的状态，也很明白你无法跟那个人切断关系，可是，如果你把离不开他的理由归结为‘那些人很强大，而我没有那么大的力量’，那你今后还能有什么改善的余地呢？”或者说：“你这是弱者对弱者的歧视，我绝对不认可这样的看法。”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-017" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>017</span><div data-v-2f4d61ed><p data-v-2f4d61ed>就是找借口呀。为了正当化什么都不做的自己，不惜一切手段。<br data-v-2f4d61ed>信田　那是因为她们不去改变现状，安于现状的同时，却又觉得自己遭到了谴责吗？</p></div></blockquote><h2 id="压抑得久了就站不起来" tabindex="-1" data-v-2f4d61ed>压抑得久了就站不起来 <a class="header-anchor" href="#压抑得久了就站不起来" aria-label="Permalink to “压抑得久了就站不起来”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-018" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>018</span><div data-v-2f4d61ed><p data-v-2f4d61ed>人无论处在什么样的逆境中，都会为了生存而逐渐适应。她甚至付出了再也不能行走的代价去适应它。这真是超乎寻常的适应能力。</p></div></blockquote><h2 id="毁灭心理-毁灭心灵" tabindex="-1" data-v-2f4d61ed>“毁灭心理”“毁灭心灵” <a class="header-anchor" href="#毁灭心理-毁灭心灵" aria-label="Permalink to ““毁灭心理”“毁灭心灵””" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-019" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>019</span><div data-v-2f4d61ed><p data-v-2f4d61ed>比如在大学这个制度中，不论其人格，只要站在导师这个位置上，就具有加害性。因为那是发生在制度中的权力关系，我也无法阻止学生会在我面前感到有压迫感。无论我多么注意自己的言行举止，他们都无可避免地会感到压力。</p></div></blockquote><h2 id="名为-自我实现-的幻想" tabindex="-1" data-v-2f4d61ed>名为“自我实现”的幻想 <a class="header-anchor" href="#名为-自我实现-的幻想" aria-label="Permalink to “名为“自我实现”的幻想”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-020" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>020</span><div data-v-2f4d61ed><p data-v-2f4d61ed>每次学生来找我问问题，或是别人来求我做事，我都会想，自己就是把宝贵的时间拱手让给别人并靠这个生活的。但我每次也会想，如果我不愿意，大不了辞职嘛。只要我不辞职，这就是我的生意。生意嘛，就当成生意好好做得了。</p></div></blockquote><h2 id="替代-自立-的表述" tabindex="-1" data-v-2f4d61ed>替代“自立”的表述 <a class="header-anchor" href="#替代-自立-的表述" aria-label="Permalink to “替代“自立”的表述”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-021" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>021</span><div data-v-2f4d61ed><p data-v-2f4d61ed>承认“我的能力有极限”，或者说有自知之明，就意味着在明白“我能做到什么”的同时，也清楚地明白“我做不到什么”。明白要将“做不到”变为“能做到”需要什么东西。如此一来，就算自己没有那个东西，只要有能力从别处得到就好了。<br data-v-2f4d61ed>信田　但是在前面那一阶段，人还无法分清自己能做到和不能做到的事情。<br data-v-2f4d61ed>上野　是的，所以才有你说的“自·分”，也就是“分·别”。如果不能“分·别”，就无法认知自身的界限。这是理所当然的。甚至不明白自己究竟在向他人寻求什么。<br data-v-2f4d61ed>信田　你的意思就是心理咨询吧。<br data-v-2f4d61ed>上野　是的。如果不明白自己在寻求什么，就算你提出“帮我想想办法呀”，别人也不知道该怎么样才能满足你。“需要”的法语是“besoin”，也可以翻译为“欲求”，如果用另一个译语来表达，那就是“缺乏”。<br data-v-2f4d61ed>如果将自立视作自我完结，那就意味着自我的所有欲求得到了满足。我们都知道，这种自我完结是不可能实现的。“缺乏”是不可避免的。只要能够区分“自·他”，就明白自己能够满足什么，不能够满足什么，也就是明白自己缺乏了什么。缺乏并不羞耻。如果有所缺乏，那么只要掌握了能够通过外界来满足的能力，就足够了。</p></div></blockquote><h2 id="如何才能有干劲-的疑问" tabindex="-1" data-v-2f4d61ed>“如何才能有干劲”的疑问 <a class="header-anchor" href="#如何才能有干劲-的疑问" aria-label="Permalink to ““如何才能有干劲”的疑问”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-022" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>022</span><div data-v-2f4d61ed><p data-v-2f4d61ed>比如：“我无论如何都提不起劲工作时，该如何让自己有干劲呢？”<br data-v-2f4d61ed>上野　如果是我就会回答：“所谓提问，就是在提问者提出问题时，她本人已经对这个问题进行了透彻的思考。你不是已经对自己的问题做出了解答吗？无论如何都提不起劲工作。有了这个答案，你还想让我说什么呢？”</p></div></blockquote><h2 id="可爱老太太-的意识形态" tabindex="-1" data-v-2f4d61ed>“可爱老太太”的意识形态 <a class="header-anchor" href="#可爱老太太-的意识形态" aria-label="Permalink to ““可爱老太太”的意识形态”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-023" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>023</span><div data-v-2f4d61ed><p data-v-2f4d61ed>最近我渐渐被老龄问题给缠上了。我真希望那些割腕的小孩子能跟卧床不起或老年痴呆的人多接触，感觉到“我的存在不需要别人的许可和承认”​。因为那些没有用处、没有希望、无法自理的人都还活着呢。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-024" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>024</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我对于人类必须具有社会性这个看法也持有很深的疑问。我活着为什么需要别人的认可？我为什么必须要对别人有用处？难道我不这么做，就失去了活着的价值了吗？</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-025" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>025</span><div data-v-2f4d61ed><p data-v-2f4d61ed>针对女性的老龄问题，日本存在着一种通俗的意识形态，那就是“想变成可爱的老太太”​。如果不被爱，我活着就没有价值了吗？我才不在乎呢。最近面向老龄人士演讲时，我有一句话特别受欢迎。​“有人说希望自己变成一个可爱的老太太，可是我从小到大都不可爱，今后也不可能变得可爱。​”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-026" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>026</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我不可能突然变可爱。今后面对老人看护，老人必须争取无论自己可不可爱都能够得到平等看护的权利。​”说出这句话时，现场反应特别热烈。</p></div></blockquote><h2 id="啃老亦枉然-十年即破" tabindex="-1" data-v-2f4d61ed>啃老亦枉然，十年即破 <a class="header-anchor" href="#啃老亦枉然-十年即破" aria-label="Permalink to “啃老亦枉然，十年即破”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-027" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>027</span><div data-v-2f4d61ed><p data-v-2f4d61ed>父母不给孩子负面的影响，不给孩子造成负担，或者说不妨碍孩子生活，就是最大的馈赠</p></div></blockquote><h2 id="活出自我的-40代-母亲" tabindex="-1" data-v-2f4d61ed>活出自我的“40代”母亲 <a class="header-anchor" href="#活出自我的-40代-母亲" aria-label="Permalink to “活出自我的“40代”母亲”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-028" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>028</span><div data-v-2f4d61ed><p data-v-2f4d61ed>姑娘直接成了妻子，又直接成了母亲，中间只发生了身份称呼的转化，而没有心理上的角色转化，所以被别人说点什么她们就很容易受伤。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-029" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>029</span><div data-v-2f4d61ed><p data-v-2f4d61ed>有的母亲一旦受伤就会爆发—“凭什么都怪我！”丝毫没有成熟的应对</p></div></blockquote><h2 id="中产阶级的瓦解改变了家庭" tabindex="-1" data-v-2f4d61ed>中产阶级的瓦解改变了家庭 <a class="header-anchor" href="#中产阶级的瓦解改变了家庭" aria-label="Permalink to “中产阶级的瓦解改变了家庭”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-030" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>030</span><div data-v-2f4d61ed><p data-v-2f4d61ed>父母没有意识到自己还是孩子，却不允许孩子当一个孩子。</p></div></blockquote><h2 id="年轻男子的女性化与dv的关系" tabindex="-1" data-v-2f4d61ed>年轻男子的女性化与DV的关系 <a class="header-anchor" href="#年轻男子的女性化与dv的关系" aria-label="Permalink to “年轻男子的女性化与DV的关系”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-031" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>031</span><div data-v-2f4d61ed><p data-v-2f4d61ed>越是沉浸在虚拟世界的人，对真实女性的幻想就越不现实</p></div></blockquote><h2 id="非婚化有可能缓解吗" tabindex="-1" data-v-2f4d61ed>非婚化有可能缓解吗？ <a class="header-anchor" href="#非婚化有可能缓解吗" aria-label="Permalink to “非婚化有可能缓解吗？”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-032" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>032</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我认为应该会有越来越多头脑冷静的婚姻，也就是“结婚并不会决定一切”的婚姻。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-033" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>033</span><div data-v-2f4d61ed><p data-v-2f4d61ed>女性也开始认为婚姻不会改变自己的人生，即使结了婚也可以走自己的女孩之路。</p></div></blockquote><h2 id="那-我们-该怎么办" tabindex="-1" data-v-2f4d61ed>那“我们”该怎么办？ <a class="header-anchor" href="#那-我们-该怎么办" aria-label="Permalink to “那“我们”该怎么办？”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-034" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>034</span><div data-v-2f4d61ed><p data-v-2f4d61ed>需要有承认自己是弱者的力量。因为不寻求援助的人，就无法得到援助。</p></div></blockquote><h2 id="后记" tabindex="-1" data-v-2f4d61ed>后记 <a class="header-anchor" href="#后记" aria-label="Permalink to “后记”" data-v-2f4d61ed>​</a></h2><blockquote class="reading-excerpt" id="excerpt-035" data-v-2f4d61ed><span class="reading-excerpt-number" aria-hidden="true" data-v-2f4d61ed>035</span><div data-v-2f4d61ed><p data-v-2f4d61ed>我认为，只关注自己的“心灵”​，追求“治愈”这种寒酸的话语，其实就像给卷心菜剥皮，只能充当自我安慰，不能解决任何问题</p></div></blockquote><footer class="reading-footer" data-v-2f4d61ed><span data-v-2f4d61ed>书籍来源：微信读书</span><span data-v-2f4d61ed>整理时间：2025年</span></footer>',62))])])}const _=r(v,[["render",h],["__scopeId","data-v-2f4d61ed"]]);export{q as __pageData,_ as default};
